result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/smooth.py", "content": """"A* pathfinding + line-of-sight string pulling on a grid."""

import heapq

GRID = [
    "S---------",
    "-########-",
    "----------",
    "-########-",
    "---------G",
]

H, W = len(GRID), len(GRID[0])
OPEN = {c for r, row in enumerate(GRID) for c, ch in enumerate(row) if ch != "#"}


def start_goal():
    s = g = None
    for r, row in enumerate(GRID):
        for c, ch in enumerate(row):
            if ch == "S":
                s = (r, c)
            elif ch == "G":
                g = (r, c)
    return s, g


def astar(start, goal):
    """4-connected A* with Manhattan heuristic."""
    def h(p):
        return abs(p[0] - goal[0]) + abs(p[1] - goal[1])

    openq = [(h(start), 0, start)]
    came, gscore = {}, {start: 0}
    while openq:
        _, g, cur = heapq.heappop(openq)
        if cur == goal:
            path = [cur]
            while cur in came:
                cur = came[cur]
                path.append(cur)
            return path[::-1]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nb = (cur[0] + dr, cur[1] + dc)
            if nb not in OPEN:
                continue
            ng = g + 1
            if ng < gscore.get(nb, float("inf")):
                gscore[nb] = ng
                came[nb] = cur
                heapq.heappush(openq, (ng + h(nb), ng, nb))
    raise ValueError("no path")


def line_of_sight(a, b):
    """Bresenham line between cells a and b crosses only open cells."""
    (r0, c0), (r1, c1) = a, b
    dr, dc = abs(r1 - r0), abs(c1 - c0)
    sr = 1 if r0 < r1 else -1
    sc = 1 if c0 < c1 else -1
    err = dc - dr
    r, c = r0, c0
    while True:
        if (r, c) not in OPEN:
            return False
        if (r, c) == (r1, c1):
            return True
        e2 = 2 * err
        if e2 > -dr:
            err -= dr
            c += sc
        if e2 < dr:
            err += dc
            r += sr


def smooth(path):
    """Greedy string pulling: keep a waypoint only when LOS to it fails."""
    out = [path[0]]
    i = 0
    while i < len(path) - 1:
        j = len(path) - 1
        while j > i + 1 and not line_of_sight(path[i], path[j]):
            j -= 1
        out.append(path[j])
        i = j
    return out


def euclidean_length(path):
    return sum(
        ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5
        for a, b in zip(path, path[1:])
    )


if __name__ == "__main__":
    s, g = start_goal()
    raw = astar(s, g)
    sm = smooth(raw)
    print(f"raw waypoints:      {len(raw)}")
    print(f"smoothed waypoints: {len(sm)}")
    print("smoothed:", sm)
